import XCTest
import UIKit
import ImageIO
@testable import Passport
final class NativeTests:XCTestCase{
    func directory()->URL{FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)}
    func entry(_ name:String,visit:Bool=true)->Entry{var r=Entry.new(visit:visit);r["name"]=name;return r}
    @MainActor func testSaveEditPhotoReloadAndUndoPreserveUnknownFields()throws{let dir=directory();defer{try? FileManager.default.removeItem(at:dir)};let store=PassportStore(directory:dir);var r=entry("Example");r["custom"]="Keep";r["photo"]="data:image/jpeg;base64,"+Data("fixture".utf8).base64EncodedString();try store.save(r,type:"visits");let before=store.archive;r["name"]="Edited";try store.save(r,type:"visits");let loaded=PassportStore(directory:dir);XCTAssertEqual(loaded.archive.entries("visits")[0]["custom"],"Keep");XCTAssertNotNil(loaded.archive.entries("visits")[0].photoData);try loaded.undo();XCTAssertEqual(loaded.archive,before)}
    @MainActor func testMarkVisitedIsAtomicAndUndoRestoresSavedPlace()throws{let dir=directory();defer{try? FileManager.default.removeItem(at:dir)};let store=PassportStore(directory:dir);let saved=entry("Want",visit:false);try store.save(saved,type:"wants");let before=store.archive;var bad=entry("Visit");bad["date"]="bad";XCTAssertThrowsError(try store.save(bad,type:"visits",removingWant:saved.id));XCTAssertEqual(store.archive,before);try store.save(entry("Visit"),type:"visits",removingWant:saved.id);XCTAssertTrue(store.archive.entries("wants").isEmpty);try store.undo();XCTAssertEqual(store.archive,before)}
    @MainActor func testImportMergesAndDeletionCanUndo()throws{let dir=directory();defer{try? FileManager.default.removeItem(at:dir)};let store=PassportStore(directory:dir);let original=entry("Original");try store.save(original,type:"visits");var incoming=PassportArchive();incoming.set("visits",[entry("Imported")]);try store.restore(incoming);XCTAssertEqual(store.archive.entries("visits").count,2);store.remove(original,type:"visits");XCTAssertEqual(store.archive.entries("visits").count,1);try store.undo();XCTAssertEqual(store.archive.entries("visits").count,2)}
    @MainActor func testCorruptStorageIsNeverSilentlyOverwritten()throws{let dir=directory();defer{try? FileManager.default.removeItem(at:dir)};try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);let raw=Data("corrupt".utf8);try raw.write(to:dir.appendingPathComponent("passport.json"));let store=PassportStore(directory:dir);XCTAssertNotNil(store.storageError);XCTAssertThrowsError(try store.save(entry("New"),type:"visits"));XCTAssertEqual(try store.originalData(),raw)}
    @MainActor func testPhotoResizesOnDeviceAndRejectsUnreadableData()async throws{let image=UIGraphicsImageRenderer(size:CGSize(width:1800,height:1000)).image{c in UIColor.white.setFill();c.fill(CGRect(x:0,y:0,width:1800,height:1000))};let output=try await PassportPhoto.jpeg(XCTUnwrap(image.pngData()));let source=try XCTUnwrap(CGImageSourceCreateWithData(output as CFData,nil));let props=try XCTUnwrap(CGImageSourceCopyPropertiesAtIndex(source,0,nil) as? [String:Any]);XCTAssertLessThanOrEqual(props[kCGImagePropertyPixelWidth as String] as! Int,1400);do{_=try await PassportPhoto.jpeg(Data("bad".utf8));XCTFail("Must reject invalid image")}catch{}}
}
final class FixtureProtocol:URLProtocol{
    static var response:((URLRequest)throws->(Int,Data))?
    override class func canInit(with request:URLRequest)->Bool{true}
    override class func canonicalRequest(for request:URLRequest)->URLRequest{request}
    override func startLoading(){do{let(status,data)=try Self.response!(request);client?.urlProtocol(self,didReceive:HTTPURLResponse(url:request.url!,statusCode:status,httpVersion:nil,headerFields:["Content-Type":"application/json"])!,cacheStoragePolicy:.notAllowed);client?.urlProtocol(self,didLoad:data);client?.urlProtocolDidFinishLoading(self)}catch{client?.urlProtocol(self,didFailWithError:error)}}
    override func stopLoading(){}
}
final class DiscoveryClientTests:XCTestCase{
    func client(_ endpoint:String="https://discovery.example.org")->DiscoveryClient{let c=URLSessionConfiguration.ephemeral;c.protocolClasses=[FixtureProtocol.self];return DiscoveryClient(endpoint:endpoint,accessCode:"fixture-code",configuration:c)}
    override func tearDown(){FixtureProtocol.response=nil}
    func testRequestContainsOnlySelectedAreaAndHeaderCode()async throws{FixtureProtocol.response={req in XCTAssertEqual(req.httpMethod,"POST");XCTAssertEqual(req.url?.path,"/api/popular");XCTAssertEqual(req.value(forHTTPHeaderField:"X-Access-Token"),"fixture-code");XCTAssertFalse(req.url!.absoluteString.contains("fixture-code"));return(200,Data(#"{"places":[],"ranking":"Popularity, not trend growth"}"#.utf8))};let result=try await client().request("popular",body:["lat":.number(0),"lon":.number(0),"radius":.number(1000)]);XCTAssertEqual(result.object.list("places"),[])}
    func testErrorsAndUnsupportedEndpointsDoNotFabricateSuggestions()async{for status in [401,429,503]{FixtureProtocol.response={_ in(status,Data(#"{"error":"Provider unavailable"}"#.utf8))};do{_=try await client().request("status");XCTFail("Must fail")}catch{}};FixtureProtocol.response={_ in XCTFail("Must not network");return(200,Data())};do{_=try await client("http://insecure.example").request("popular");XCTFail("Must reject HTTP")}catch{};do{_=try await client().request("arbitrary");XCTFail("Must reject path")}catch{}}
    func testOfflineFailsHonestly()async{FixtureProtocol.response={_ in throw URLError(.notConnectedToInternet)};do{_=try await client().request("popular");XCTFail("Must not return mock places")}catch{}}
}
